/* Desktop: the waitlist bar is the wrapper's last child with position: sticky; bottom: 0, so
   it rides the bottom of the window across every section it wraps and settles under the
   closing heading at the end.

   Two pairs of layers make it breathe: the outer layers shrink it once the page starts to
   move (bar slides 44px down so the small print leaves the window, button scales to 85%)
   over the first 450px of scroll; the inner layers undo exactly that while the closing
   heading rises into view (the heading publishes a named view timeline, the wrapper widens
   its scope so the bar can follow it). */
.diabrowser-waitlist-dock {
  timeline-scope: --diabrowser-waitlist-dock-closer;
}
.diabrowser-waitlist-dock-heading {
  view-timeline-name: --diabrowser-waitlist-dock-closer;
}

@supports (animation-timeline: view()) {
  @media (prefers-reduced-motion: no-preference) {
    .diabrowser-waitlist-dock-fade {
      animation: diabrowser-waitlist-dock-fade linear both;
      animation-timeline: view();
      animation-range: entry 0px entry 120px;
    }
  }
}

@supports (animation-timeline: scroll()) and (timeline-scope: none) {
  @media (min-width: 64rem) and (prefers-reduced-motion: no-preference) {
    .diabrowser-waitlist-dock-slide-a,
    .diabrowser-waitlist-dock-scale-a {
      animation: diabrowser-waitlist-dock-slide-down linear both;
      animation-timeline: scroll(root);
      animation-range: 0 450px;
    }
    .diabrowser-waitlist-dock-scale-a {
      animation-name: diabrowser-waitlist-dock-shrink;
    }
    .diabrowser-waitlist-dock-slide-b,
    .diabrowser-waitlist-dock-scale-b {
      animation: diabrowser-waitlist-dock-slide-up linear both;
      animation-timeline: --diabrowser-waitlist-dock-closer;
      animation-range: cover 100px cover 300px;
    }
    .diabrowser-waitlist-dock-scale-b {
      animation-name: diabrowser-waitlist-dock-grow;
    }
  }
}

@keyframes diabrowser-waitlist-dock-fade {
  from { opacity: 0; }
}
@keyframes diabrowser-waitlist-dock-slide-down {
  to { translate: 0 44px; }
}
@keyframes diabrowser-waitlist-dock-shrink {
  to { scale: 0.85; }
}
@keyframes diabrowser-waitlist-dock-slide-up {
  from { translate: 0 0; }
  to { translate: 0 -44px; }
}
@keyframes diabrowser-waitlist-dock-grow {
  from { scale: 1; }
  to { scale: 1.1765; }
}

import type { ReactNode } from "react";
import { DiabrowserHeading } from "@foundry/diabrowser-heading";
import { DiabrowserWaitlistBar, type DiabrowserWaitlistBarProps } from "@foundry/diabrowser-waitlist-bar";
import { cn } from "@foundry/foundry-utils";
import "./diabrowser-waitlist-dock.css";

export interface DiabrowserWaitlistDockProps {
  /** the page sections the bar rides along with (hero to the last section before the closer) */
  children?: ReactNode;
  /** the closing serif line the bar settles under */
  heading: ReactNode;
  /** the black CTA on the arc */
  cta: DiabrowserWaitlistBarProps["cta"];
  /** small print under the CTA */
  note?: ReactNode;
  className?: string;
}

/**
 * Wraps the page so its waitlist bar stays docked at the bottom of the window on desktop,
 * shrinking once you scroll and growing back as it settles under the closing heading.
 * Phones: the closing heading followed by the bar, in place.
 */
export function DiabrowserWaitlistDock({ children, heading, cta, note, className }: DiabrowserWaitlistDockProps) {
  return (
    <div className={cn("diabrowser-waitlist-dock relative bg-background text-foreground", className)}>
      {children}
      <section className="diabrowser-waitlist-dock-fade px-gutter pb-[96px] lg:pt-[30px]">
        <DiabrowserHeading className="diabrowser-waitlist-dock-heading">{heading}</DiabrowserHeading>
      </section>
      {/* must stay the wrapper's last child: sticky bottom holds only while its own spot is below the fold */}
      <div className="z-40 lg:sticky lg:bottom-0">
        <div className="diabrowser-waitlist-dock-slide-a">
          <div className="diabrowser-waitlist-dock-slide-b">
            <DiabrowserWaitlistBar cta={cta} note={note} buttonLayers={["diabrowser-waitlist-dock-scale-a", "diabrowser-waitlist-dock-scale-b"]} />
          </div>
        </div>
      </div>
    </div>
  );
}
